$ftp = [System.Net.FtpWebRequest]::Create("ftp://#{ftp.server.address}/$RemoteName");
$ftp = [System.Net.FTPWebRequest]$ftp;
$ftp.Method = [System.Net.WebRequestMethods+Ftp]::UploadFile;
